(6384813, 946017, 65234, '<td valign="top">Great "pose" on those columbines!  I think I''d have blurred the background a bit more and, since this is a cool challenge, shifted/tinted the yellow softness in the background to blue or green.</td>', 'Great "pose" on those columbines!  I think I''d have blurred the background a bit more and, since this is a cool challenge, shifted/tinted the yellow softness in the background to blue or green.', '2011-04-13 09:58:29.000000', NULL, 1),
(6384817, 946067, 65234, '<td valign="top">Pretty little flower.  Looks like there''s a bit of color fringing around the edges of the OOF bits where purple meets green; I''d blur those more to minimize that effect.</td>', 'Pretty little flower.  Looks like there''s a bit of color fringing around the edges of the OOF bits where purple meets green; I''d blur those more to minimize that effect.', '2011-04-13 10:01:01.000000', NULL, 1),
(6384823, 946065, 65234, '<td valign="top">Lots of green here; quite lush.  The yellow looks oversaturated on my screen, and I think I''d shift the greens a little towards blue and desaturate them, too, to make the "mood" of the scene darker/cooler.</td>', 'Lots of green here; quite lush.  The yellow looks oversaturated on my screen, and I think I''d shift the greens a little towards blue and desaturate them, too, to make the "mood" of the scene darker/cooler.', '2011-04-13 10:04:33.000000', NULL, 1),
