(6385262, 946092, 2553, '<td valign="top">So cool!Superb colors too.</td>', 'So cool!Superb colors too.', '2011-04-13 15:45:48.000000', NULL, 1),
(6385264, 945981, 2553, '<td valign="top">So beautiful and fun!  Don''t know how  you do it...I''d get SO confused with that many pieces of paper to put together.</td>', 'So beautiful and fun!  Don''t know how  you do it...I''d get SO confused with that many pieces of paper to put together.', '2011-04-13 15:46:30.000000', NULL, 1),
(6385267, 945821, 2553, '<td valign="top">I find this image very appealing.  I think it''s the texture behind the vines that just adds so much to the image.  Nice!</td>', 'I find this image very appealing.  I think it''s the texture behind the vines that just adds so much to the image.  Nice!', '2011-04-13 15:47:25.000000', NULL, 1),
(6385269, 945826, 2553, '<td valign="top">OK, back for commenting and a second good look.  First this made me laugh...then look at it...then really think about it, and smile.  So unexpected, to see such a sight.  LOVE it though, bumping from a 9 to a 10, just because it''s so cool. And weird.  LOL.</td>', 'OK, back for commenting and a second good look.  First this made me laugh...then look at it...then really think about it, and smile.  So unexpected, to see such a sight.  LOVE it though, bumping from a 9 to a 10, just because it''s so cool. And weird.  LOL.', '2011-04-13 15:49:58.000000', NULL, 1),
(6385403, 945650, 61961, '<td valign="top">Tough call, sometimes green seems more warm than cool.  I like how the seats fill the frame.  (No vote for now.)</td>', 'Tough call, sometimes green seems more warm than cool.  I like how the seats fill the frame.  (No vote for now.)', '2011-04-13 17:31:49.000000', NULL, 1),
