INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6389622, 946044, 96751, '<td valign="top">Spectacular.  Storms are so photogenic and sexy.</td>', 'Spectacular.  Storms are so photogenic and sexy.', '2011-04-18 17:50:41.000000', NULL, 1),
(6389626, 945986, 96751, '<td valign="top">This is such a frustrating image to me.  Individually, the elements are wonderful, the items are interesting, the colors work really well together.  But collectively, I don''t like the composition - it looks messy</td>', 'This is such a frustrating image to me.  Individually, the elements are wonderful, the items are interesting, the colors work really well together.  But collectively, I don''t like the composition - it looks messy', '2011-04-18 17:53:49.000000', NULL, 1),
(6389627, 945387, 96751, '<td valign="top">An aquatic mushroom</td>', 'An aquatic mushroom', '2011-04-18 17:54:08.000000', NULL, 1),
(6389629, 945695, 96751, '<td valign="top">very interesting foreground, and the silhouette really adds a point of interest.</td>', 'very interesting foreground, and the silhouette really adds a point of interest.', '2011-04-18 17:54:50.000000', NULL, 1),
(6389630, 946077, 96751, '<td valign="top">Brilliant makeup (although I''m not sure why the undereyes were left natural) and nicely lit.  Love the mist!  This will finish on the front page.</td>', 'Brilliant makeup (although I''m not sure why the undereyes were left natural) and nicely lit.  Love the mist!  This will finish on the front page.', '2011-04-18 17:55:36.000000', NULL, 1),
(6389631, 945807, 96751, '<td valign="top">Gorgeous.  Oddly, I can see this being much more powerful in b/w.</td>', 'Gorgeous.  Oddly, I can see this being much more powerful in b/w.', '2011-04-18 17:56:10.000000', NULL, 1),
(6389632, 946128, 96751, '<td valign="top">Lovely tones and bokeh</td>', 'Lovely tones and bokeh', '2011-04-18 17:56:45.000000', NULL, 1),
(6389635, 946089, 96751, '<td valign="top">Love the tones.  I could see this as a screensaver or a stationary bg.</td>', 'Love the tones.  I could see this as a screensaver or a stationary bg.', '2011-04-18 17:58:23.000000', NULL, 1),
(6389636, 945858, 96751, '<td valign="top">Really odd flower, which looks like plastic!  Nice macro</td>', 'Really odd flower, which looks like plastic!  Nice macro', '2011-04-18 17:59:01.000000', NULL, 1),
(6389637, 946131, 96751, '<td valign="top">Interesting.  I really like this image, and the "found filter" created by the water surface.  I even like the motion blur and the bokeh/texture of the branch.  But this is almost a b/w image and has not much color of any temperature.</td>', 'Interesting.  I really like this image, and the "found filter" created by the water surface.  I even like the motion blur and the bokeh/texture of the branch.  But this is almost a b/w image and has not much color of any temperature.', '2011-04-18 18:00:00.000000', NULL, 1),
(6389639, 945983, 96751, '<td valign="top">Nice, Jenn.  A standout in the challenge.</td>', 'Nice, Jenn.  A standout in the challenge.', '2011-04-18 18:08:16.000000', NULL, 1),
(6389641, 946063, 96751, '<td valign="top">Well, I''m going through the challenge and think this just might be Ben''s image.  I actually really like this (regardless of whether or not this IS Ben''s...).  Nicely balanced, with the stone anchoring one end and the orange line the other.  I especially like the warm glow of beachfront homes on the horizon.  This image makes me feel both cozy and melancholic at the same time.</td>', 'Well, I''m going through the challenge and think this just might be Ben''s image.  I actually really like this (regardless of whether or not this IS Ben''s...).  Nicely balanced, with the stone anchoring one end and the orange line the other.  I especially like the warm glow of beachfront homes on the horizon.  This image makes me feel both cozy and melancholic at the same time.', '2011-04-18 18:10:25.000000', NULL, 1),
(6389642, 945406, 96751, '<td valign="top">The tones almost look metallic</td>', 'The tones almost look metallic', '2011-04-18 18:10:53.000000', NULL, 1),
(6389647, 945364, 96751, '<td valign="top">I like that lone tree</td>', 'I like that lone tree', '2011-04-18 18:16:18.000000', NULL, 1),
(6389650, 945956, 96751, '<td valign="top">Very sweet.  Not liking ALL that empty space.  This would work better for me if it were more of a square crop.</td>', 'Very sweet.  Not liking ALL that empty space.  This would work better for me if it were more of a square crop.', '2011-04-18 18:17:23.000000', NULL, 1),
(6389651, 945843, 96751, '<td valign="top">Sweet.  I like the moment.</td>', 'Sweet.  I like the moment.', '2011-04-18 18:17:41.000000', NULL, 1),
(6389652, 945650, 96751, '<td valign="top">To me, this is actually a warm green - might have been better in that challenge :-)</td>', 'To me, this is actually a warm green - might have been better in that challenge :-)', '2011-04-18 18:18:03.000000', NULL, 1),
(6389653, 946113, 96751, '<td valign="top">Beautiful reflections</td>', 'Beautiful reflections', '2011-04-18 18:18:12.000000', NULL, 1),
(6389655, 945872, 96751, '<td valign="top">Loving the bands of blue in the water</td>', 'Loving the bands of blue in the water', '2011-04-18 18:18:37.000000', NULL, 1),
(6389656, 946097, 96751, '<td valign="top">Gorgeous.  Technically flawless - expect this to finish near the top.</td>', 'Gorgeous.  Technically flawless - expect this to finish near the top.', '2011-04-18 18:19:05.000000', NULL, 1),
(6389658, 946098, 96751, '<td valign="top">Love this tire abstract.  Great textures and colors.</td>', 'Love this tire abstract.  Great textures and colors.', '2011-04-18 18:19:29.000000', NULL, 1),
(6389660, 946006, 96751, '<td valign="top">Love the alien planet portion of the shot.  The perspective is really odd on the dog (makes his rump look huge and his front look miniature), and the sky is a bit much...<br/> <br/>Will probably finish near the top.</td>', 'Love the alien planet portion of the shot.  The perspective is really odd on the dog (makes his rump look huge and his front look miniature), and the sky is a bit much... Will probably finish near the top.', '2011-04-18 18:20:38.000000', NULL, 1),
(6389662, 944939, 96751, '<td valign="top">This could be a very nice portrait but there are several elements which do not work for me.  Although the rocks make a great bg, the desat takes away elements that would make him stand out more from that bg - there are too many textures and he sort of blends in a bit.  Also, his attitude is great, but I do not care for his spread-leg pose.  Very unbecoming.</td>', 'This could be a very nice portrait but there are several elements which do not work for me.  Although the rocks make a great bg, the desat takes away elements that would make him stand out more from that bg - there are too many textures and he sort of blends in a bit.  Also, his attitude is great, but I do not care for his spread-leg pose.  Very unbecoming.', '2011-04-18 18:22:42.000000', NULL, 1),
(6389663, 945409, 96751, '<td valign="top">Neat!!!  Could be floating in water :-)</td>', 'Neat!!!  Could be floating in water :-)', '2011-04-18 18:23:10.000000', NULL, 1),
(6389665, 945981, 96751, '<td valign="top">Lovely postit shot.  Looks like a kaleidoscope.</td>', 'Lovely postit shot.  Looks like a kaleidoscope.', '2011-04-18 18:23:33.000000', NULL, 1),
(6389666, 946039, 96751, '<td valign="top">Love it.  Like destiny flying through the architecture of our mind.</td>', 'Love it.  Like destiny flying through the architecture of our mind.', '2011-04-18 18:24:38.000000', NULL, 1),
(6389667, 945942, 96751, '<td valign="top">A bad dream manifested tastefully.  <br/> <br/>Now I''m suspecting my previous guess at the author of the another image...</td>', 'A bad dream manifested tastefully.   Now I''m suspecting my previous guess at the author of the another image...', '2011-04-18 18:25:55.000000', NULL, 1),
(6389668, 946094, 96751, '<td valign="top">Nice graphic quality</td>', 'Nice graphic quality', '2011-04-18 18:26:05.000000', NULL, 1),
