(6389822, 945134, 98339, '<td valign="top">technically this is a type of Agave Americana Plant, this one seems quite green, the ones that I''ve seen around here usually have a strong hint of blue/gray to them.  They are quite large (or will get very large)...the "teeth" on them will rip you apart for sure.</td>', 'technically this is a type of Agave Americana Plant, this one seems quite green, the ones that I''ve seen around here usually have a strong hint of blue/gray to them.  They are quite large (or will get very large)...the "teeth" on them will rip you apart for sure.', '2011-04-18 20:36:00.000000', NULL, 1),
(6389834, 946044, 117037, '<td valign="top">Well done.</td>', 'Well done.', '2011-04-18 21:25:09.000000', NULL, 1),
